namespace ghidra.app.cmd.function;

using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.listing;

/**
 * Command for removing a tag from a function
 */
public class RemoveFunctionTagCmd : Command<Program> {

	private Address entryPoint;
	private string tagName;

	/**
	 * Constructor
	 * 
	 * @param tagName the name of the tag to remove
	 * @param entryPoint the address of the function
	 */
	public RemoveFunctionTagCmd(string tagName, Address entryPoint) {
		this.tagName = tagName;
		this.entryPoint = entryPoint;
	}

	/* @Override */
	public bool applyTo(Program program) {
		FunctionManager functionManager = program.getFunctionManager();
		Function function = functionManager.getFunctionAt(entryPoint);
		function.removeTag(tagName);
		return true;
	}

	/* @Override */
	public string getName() {
		return "Remove Tag From Function";
	}

	/* @Override */
	public string getStatusMsg() {
		return null;
	}
}
